def max_value_on_paths(N: int, grid_values: List[Tuple[int, int, int]]) -> int:
    # Initialize a 2D array to store the maximum sum of values collected on each path
    max_sums = [[0] * N for _ in range(N)]

    # Iterate over the grid values and update the maximum sum for each path
    for x, y, value in grid_values:
        if x == 0 and y == 0:
            max_sums[x][y] = value
        elif x == N - 1 and y == N - 1:
            max_sums[x][y] = value
        elif x == 0 and y == 1:
            max_sums[x][y] = max(value, max_sums[0][y - 1])
        elif x == 1 and y == 0:
            max_sums[x][y] = max(value, max_sums[x - 1][0])
        elif x == N - 1 and y == N - 2:
            max_sums[x][y] = max(value, max_sums[x][N - 1])
        elif x == N - 2 and y == N - 1:
            max_sums[x][y] = max(value, max_sums[N - 1][y - 1])
        else:
            max_sums[x][y] = max(value, max_sums[x - 1][y - 1], max_sums[x - 1][y], max_sums[x][y - 1])

    # Return the maximum sum of values collected on both paths
    return max(max_sums[N - 1][N - 1], max_sums[N - 1][0], max_sums[0][N - 1])
