def max_value_on_paths(N, grid_values):
    def recursive(x, y, memo):
        if x == N - 1 and y == N - 1:
            return grid_values[x][y]
        if x == N or y == N:
            return 0
        if (x, y) in memo:
            return memo[(x, y)]
        memo[(x, y)] = max(
            recursive(x, y + 1, memo) + grid_values[x][y],
            recursive(x + 1, y, memo) + grid_values[x][y],
        )
        return memo[(x, y)]

    return max(recursive(0, 0, {}), recursive(0, 1, {}))
