    if not isinstance(N, int):
        raise ValueError("N must be an integer")
    if not isinstance(K, int):
        raise ValueError("K must be an integer")
    if num_str.count("*") > 0:
        raise ValueError("num_str should not contain '*'")
    if N < K or N - K < 0:
        raise ValueError("N must be greater than or equal to K")

    # Initialize variables
    max_product = 0
    nums = num_str.split()
    for i in range(K):
        nums[i] = int(nums[i])
        nums[i + 1] = int(nums[i + 1])

    # Iterate through all possible combinations of multiplication signs
    for i in range(1, len(nums) - 1):
        product = reduce(lambda x, y: x * y, nums[:i]) \
                    * reduce(lambda x, y: x * y, nums[i + 1:])
        if product > max_product:
            max_product = product

    return max_product
