def preorder_traversal(inorder: str, postorder: str) -> str:
    # Reconstruct the binary tree from the given traversals
    root = None
    for i in range(len(inorder) - 1, -1, -1):
        node = Node(postorder[i])
        if root is None:
            root = node
        else:
            # Insert the new node into the tree
            parent = find_parent(root, node.value)
            node.left = parent.left
            node.right = parent.right
            parent.left = node
        # Update the remaining traversals
        inorder = inorder[:i] + inorder[i + 1:]
        postorder = postorder[:i] + postorder[i + 1:]
    # Preorder traversal
    return preorder(root)

def find_parent(node: Node, value: str) -> Node:
    if node is None:
        return None
    if node.left and value in node.left.values():
        return node
    if node.right and value in node.right.values():
        return node
    return find_parent(node.left, value) or find_parent(node.right, value)

def preorder(node: Node) -> str:
    if node is None:
        return None
    return node.value + preorder(node.left) + preorder(node.right)

