        def __init__(self, word: str, depth: int):
            self.word = word
            self.depth = depth

    class Solution:
        def __init__(self, word: str):
            self.word = word
            self.depth = 0
            self.breadth_first_search()

        def breadth_first_search(self):
            queue = [Node(self.word, self.depth)]
