            while queue:
                current = queue.pop(0)
                if current.word == B:
                    return current.depth
                if current.word not in visited:
                    for rule in rules:
                        new_word = current.word.replace(rule[0], rule[1])
                        queue.append(Node(new_word, current.depth + 1))
                        visited.add(new_word)
            return "NO ANSWER!"

    solution = Solution(A)
    return solution.breadth_first_search()
